').onclick=clientBrief;$('#modeSelect').onchange=e=>{state.mode=e.target.value;$('#lookLabel').textContent=e.target.value;toast(`${state.mode} selected`)};$('#modalCancel').onclick=()=>$('#modalBack').classList.remove('show');$('#modalOk').onclick=()=>$('#modalBack').classList.remove('show');$('#modalBack').onclick=e=>{if(e.target.id==='modalBack')e.currentTarget.classList.remove('show')};$$('.mobile-nav [data-scroll]').forEach(b=>b.onclick=()=>{document.querySelector('.'+b.dataset.scroll)?.scrollIntoView({behavior:'smooth'});$$('.mobile-nav button').forEach(x=>x.classList.toggle('active',x===b))});
const svg=$('#faceSvg');svg.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;svg.setPointerCapture(e.pointerId);paint(e);});svg.addEventListener('pointermove',e=>{if(e.buttons&&state.action==='apply')paint(e,true)});svg.addEventListener('pointerup',()=>{state.stroke=null;});
