function updateBrush(){ $('#toolText').textContent=state.tool;$('#sizeText').textContent=state.size+' px';$('#pressureText').textContent=state.pressure+'%';}
function paint(e,drag=false){let p=palette[state.category].products[state.product];if(state.category===7&&state.product>0){toast('Choose any brush using the Tool selector, then pick a makeup category to apply');return;}if(state.action==='erase'){eraseAt(e);return;}let rect=$('#faceSvg').getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*500,y=(e.clientY-rect.top)/rect.height*650;let category=palette[state.category].name, pname=p[0],hex=shadeSet[state.shade],id='m'+Date.now()+Math.random().toString(16).slice(2,5);if(category==='Tools'){toast('Tool selected — choose a product category to apply makeup');return;}if(['Hair & nails','Accessories'].includes(category)){specialApply(category,pname,hex);return;}if(state.tool==='Beauty blender'||state.tool==='Mini sponge'||state.tool==='Powder puff'){if(state.layers.length){let last=state.layers[state.layers.length-1];last.opacity=Math.min(100,last.opacity+8);last.blur=Math.min(14,(last.blur||0)+1);renderLayers();return;}}
if(!state.stroke){saveHistory();state.stroke={id,cat:category,pname,hex,finish:state.finish,opacity:Math.round(state.opacity*state.pressure/100),tool:state.tool,size:state.size,points:[],blur:0};state.layers.push(state.stroke);}state.stroke.points.push({x,y});if(!drag||state.stroke.points.length%2===0)renderLayers();state.score=Math.min(99,state.score+0.22);updateScore();}
function typeFor(cat,name){let n=name.toLowerCase();if(cat==='Skincare')return n.includes('lip')?'lip':'base';if(cat==='Complexion'){if(/foundation|tint|bb cream|cc cream|corrector|concealer|powder|spray/.test(n))return 'base';if(/contour|bronzer/.test(n))return 'contour';if(/blush/.test(n))return 'blush';if(/highlighter/.test(n))return 'highlight';}if(cat==='Brows')return 'brow';if(cat==='Eyes'){if(/liner|kohl/.test(n))return 'liner';if(/mascara/.test(n))return 'lash';if(/lash set/.test(n))return 'falseLash';return 'shadow';}if(cat==='Lips')return 'lip';return 'base';}
function renderLayers(){let html='';for(const l of state.layers){let type=typeFor(l.cat,l.pname),op=(l.opacity||50)/100,blur=l.blur||0;let points=l.points||[];if(type==='base'||type==='contour'||type==='blush'||type==='highlight'||type==='lip'||type==='brow'||type==='lash'||type==='falseLash'){let r=(l.size||30)*.66;for(let pt of points){if(pt.y<185||pt.y>493||pt.x<120||pt.x>380)continue;let color=l.hex;if(type==='base'&&l.cat==='Skincare')color='#f4ddcb';let opacity=op*(l.cat==='Skincare'?.20:1);html+=`<circle class="makeup-layer" cx="${pt.x}" cy="${pt.y}" r="${r}" fill="${color}" opacity="${opacity}" ${blur?`filter="url(#soft)"`:''}/>`;if(type==='highlight')html+=`<circle cx="${pt.x}" cy="${pt.y}" r="${r*.55}" fill="#fff7e5" opacity="${op*.24}" filter="url(#glow)"/>`;if(type==='lip')html+=`<circle cx="${pt.x}" cy="${pt.y}" r="${r*.7}" fill="${color}" opacity="${op*.7}"/>`;}}
else if(type==='shadow'||type==='liner'){for(let pt of points){let target=pt.y>318?'lower':pt.x<250?'left':'right';if(type==='liner'){html+=`<circle cx="${pt.x}" cy="${pt.y}" r="${Math.max(1.5,(l.size||15)/12)}" fill="${l.hex}" opacity="${op}"/>`;continue;}let rx=(l.size||26)*.72,ry=rx*.48;let cx=target==='left'?195:305,cy=target==='lower'?301:282;html+=`<ellipse class="eye-makeup" cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${l.hex}" opacity="${op*.68}" ${blur?`filter="url(#soft)"`:''}/>`;}}
}
$('#makeupLayer').innerHTML=html;}
function specialApply(category,name,hex){saveHistory();if(category==='Hair & nails'&&name.includes('Color')){let idx=shadeSet.indexOf(hex)%7;state.hairColor=idx;$('#hairColor').value=idx;applyHair();$('#hairText').textContent=hairColorName(idx);toast(`Applied ${name.toLowerCase()} to hair`);return;}if(category==='Hair & nails'&&name.includes('Nail')){toast(`${name} selected — nail shade ${hex} saved to your look`);state.score+=2;updateScore();return;}if(category==='Accessories'){if(name.includes('Hoops')||name.includes('Pearl'))state.details.piercing=true;if(name.includes('Glasses'))state.details.glasses=true;if(name.includes('Necklace'))state.studio.necklace=true;if(name.includes('Hair Pins')||name.includes('Headband'))state.studio.decor=true;updateDetails();toast(`${name} styled on your model`);state.score+=3;updateScore();return;}}
