function exportImage(){let original=$('#faceSvg'),clone=original.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width','1000');clone.setAttribute('height','1300');let data=new XMLSerializer().serializeToString(clone),url=URL.createObjectURL(new Blob([data],{type:'image/svg+xml'})),img=new Image();img.onload=()=>{let canvas=document.createElement('canvas');canvas.width=1000;canvas.height=1300;let ctx=canvas.getContext('2d');ctx.fillStyle='#f8f2ed';ctx.fillRect(0,0,1000,1300);ctx.drawImage(img,0,0,1000,1300);URL.revokeObjectURL(url);canvas.toBlob(blob=>{let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(state.lookName||'ultimate-makeup-look').replace(/[^a-z0-9]+/gi,'-').toLowerCase()+'.png';a.click();URL.revokeObjectURL(a.href);toast('Portrait exported as PNG');});};img.onerror=()=>{URL.revokeObjectURL(url);toast('Could not export portrait in this browser')};img.src=url;}
